// Pseudo-implementation: flag evaluation with cache and App Configuration
async function shouldRoute(tenantId: string, event: any) {
  const key = `flag:${tenantId}`;
  let flag = await redis.get(key);
  if (!flag) {
    flag = await appConfigClient.getFlag(tenantId);
    await redis.set(key, flag, { ttl: 300 });
